input.command:
awk '
{ lines[NR]=$0 }
/^[A-Za-z_][A-Za-z0-9_]*=/ { keys[NR]=$0; nk++ }
/^# scope:/ { mk[NR]=$0; nm++ }
END {
  printf "active KEY= lines: %d\n", nk
  printf "^# scope: markers: %d\n", nm
  print "--- per-key: walk upward from key to find scope marker ---"
  for (i=1;i<=NR;i++) if (i in keys) {
    split(keys[i], kv, "=")
    j=i-1; dist=0; found=0; path=""
    while (j>=1) {
      if (lines[j] ~ /^# scope:/) { found=j; break }
      if (lines[j] ~ /^#/) { path = path "|C:" j; j--; dist++; continue }
      if (lines[j] ~ /^[[:space:]]*$/) { path = path "|BLANK:" j; j--; dist++; continue }
      path = path "|OTHER:" j; j--; dist++
    }
    gap = (found? i-found-1 : -1)
    printf "%-4d %-45s marker=%-5s gap=%d between=%s\n", i, kv[1], (found?found:"NONE"), gap, (path==""?"-":path)
  }
}' .env.sample

cd /Users/marcel.a.n.navarro/Dev/zimmermann-pwa
awk '{l[NR]=$0} END{
  for(i=1;i<=NR;i++){
    if(l[i] !~ /^[A-Za-z_][A-Za-z0-9_]*=/) continue
    if(l[i-1] ~ /^# mrt:/ && l[i-2] ~ /^# scope:/) { both++; continue }
    if(l[i-1] ~ /^# scope:/) { scopeonly++; printf "SCOPE-ONLY (no mrt tag): key line %d  %s\n", i, l[i]; continue }
    printf "ANOMALY key line %d: %s\n   -1: %s\n   -2: %s\n", i, l[i], l[i-1], l[i-2]
  }
  printf "\nscope->mrt->KEY : %d\nscope->KEY (no mrt): %d\nanomalies: %d\n", both, scopeonly, 60-both-scopeonly
}' .env.sample

